// The todocli contract this panel is written against (PLAN §3.5, §3.7;
// appendix A5): tests/fixtures/contract/ holds what the real binary prints,
// generated by todocli's tests/contract.rs and vendored here byte for byte,
// pinned by SHA-256 the way the skill pins its oracle. The fake `todocli`
// replays those bytes by verb, so every cli-store test runs against the
// binary's own shapes; and, when a todocli binary is at hand
// (`TODOCLI_BIN`, or `todocli` on PATH), the same reads and writes are
// driven through it under a fully isolated environment, so the fixtures
// and the binary are checked against each other from this side too.
// Re-vendoring: copy the goldens over, then paste the pins this test
// prints on a mismatch.
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { lib, here } from "./helpers.mjs";

const Store = lib("Store.js");
const Queue = lib("Queue.js");
const Errors = lib("Errors.js");
const Argv = lib("Argv.js");
const dir = path.join(here, "fixtures", "contract");
const fake = path.join(here, "fakebin", "todocli");

// sha256 of every vendored golden; todocli's tests/contract.rs regenerates
// them and fails when a sibling checkout's copy differs.
