const golden = (name) => fs.readFileSync(path.join(dir, name), "utf8");
const sha = (name) => createHash("sha256").update(fs.readFileSync(path.join(dir, name))).digest("hex");

function runArgv(argv, env, extra) {
  const r = spawnSync(argv[0], argv.slice(1), Object.assign({ env: Object.assign({}, process.env, env || {}), encoding: "utf8" }, extra || {}));
  return { code: r.status === null ? -1 : r.status, stdout: r.stdout || "", stderr: r.stderr || "", spawnFailed: !!r.error };
}

test("every vendored golden is pinned, every pin has its golden, and the bytes match", () => {
  const files = fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
  assert.deepEqual(files, Object.keys(PINS).sort(), "the vendored set and the pin table name the same files");
  const drift = files.filter((f) => sha(f) !== PINS[f]);
  assert.deepEqual(drift, [], "re-vendored goldens; new pins:\n" + files.map((f) => `  "${f}": "${sha(f)}",`).join("\n"));
  for (const f of files) assert.ok(JSON.parse(golden(f)), f + " is JSON");
});

test("the goldens are the shapes this panel parses: the board, every write reply, the sync reply, the envelope of every kind", () => {
  const board = Store.fromCli(golden("board.json"));
  assert.equal(board.ok, true);
  assert.deepEqual(board.items.map((t) => [t.id, t.name, t.status]), [["3", "Wire the webhook", "doing"], ["5", "Closed one", "done"]]);
  assert.deepEqual(board.focus, { text: "Ship the invoice-export slice", taskId: "3" });
  assert.deepEqual(board.sync.map((t) => t.name), ["obsidian"], "one target since todocli S10-1 (D18)");
  assert.equal(board.stamp, "$STATE_DIR/changed", "the stamp path, normalised by the generator");
  for (const verb of ["add", "start", "done", "reopen", "step", "rm"]) {
    const reply = JSON.parse(golden("write-" + verb + ".json"));
    assert.equal(typeof reply.id, "number", verb + " replies the affected task");
    assert.equal(Queue.rememberId({}, "tmp", golden("write-" + verb + ".json")).tmp, String(reply.id));
  }
  assert.equal(JSON.parse(golden("write-rm.json")).deleted, true);
  assert.deepEqual(JSON.parse(golden("write-focus-task.json")), { focus: "Ship the invoice-export slice", focus_task: 3 });
  assert.deepEqual(JSON.parse(golden("write-focus-clear.json")), { focus: null, focus_task: null }, "--clear clears the statement and the link (todocli 07988ed)");
  assert.equal(Queue.rememberId({}, "tmp", golden("write-focus-task.json")).tmp, undefined, "a focus reply names no task to map");
  const sync = JSON.parse(golden("sync-all.json"));
  assert.deepEqual(Object.keys(sync), ["targets"], "no basecamp object (D27)");
  assert.deepEqual(sync.targets.map((t) => t.name), ["obsidian"]);
  assert.deepEqual(Object.keys(sync.targets[0]), ["name", "enabled", "lastOkAt", "lastAttemptAt", "intervalSec", "error", "state", "hint", "notices"], "no counters (D27)");
  const kinds = fs.readdirSync(dir).filter((f) => f.startsWith("envelope-")).map((f) => f.slice("envelope-".length, -".json".length)).sort();
  assert.deepEqual(kinds, ["auth", "auth_unreachable", "busy", "config", "db", "error", "list_gone", "not_found", "offline", "rate_limited", "refused", "removals_held", "sync_held", "usage"], "the frozen kind vocabulary");
  for (const kind of kinds) {
    const env = JSON.parse(golden("envelope-" + kind + ".json"));
    assert.deepEqual(Object.keys(env), ["ok", "kind", "error", "code"], kind);
    assert.equal(env.kind, kind);
    assert.deepEqual(Errors.parseEnvelope(golden("envelope-" + kind + ".json")), { kind, message: env.error });
    const classified = Errors.classifySync(env.code, golden("envelope-" + kind + ".json"), "", false);
    assert.equal(classified.kind, kind, "classifySync names the envelope's kind");
    assert.equal(classified.store, undefined, "no sync failure is a store error");
  }
});

test("the fake replays the goldens by verb and prints the real envelope on FAKE_EXIT", () => {
  assert.equal(runArgv(Argv.forAction(fake, { type: "read" })).stdout, golden("board.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "add", name: "x", description: "" })).stdout, golden("write-add.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "setStatus", id: "3", status: "done" })).stdout, golden("write-done.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "setStatus", id: "3", status: "doing" })).stdout, golden("write-start.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "setStatus", id: "3", status: "todo" })).stdout, golden("write-reopen.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "toggleStep", id: "3", n: 1 })).stdout, golden("write-step.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "focus", id: "3" })).stdout, golden("write-focus-task.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "focus", id: "clear" })).stdout, golden("write-focus-clear.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "remove", id: "3" })).stdout, golden("write-rm.json"));
  assert.equal(runArgv(Argv.forAction(fake, { type: "syncNow" })).stdout, golden("sync-all.json"));
  const held = runArgv(Argv.forAction(fake, { type: "syncNow" }), { FAKE_EXIT: "75", FAKE_KIND: "sync_held" });
  assert.equal(held.code, 75);
  assert.equal(held.stdout, golden("envelope-sync_held.json"));
  const busy = runArgv(Argv.forAction(fake, { type: "read" }), { FAKE_EXIT: "75", FAKE_STDERR: "database is busy\n" });
  assert.equal(busy.stdout, golden("envelope-busy.json"), "75 without a kind is busy");
  assert.equal(busy.stderr, "database is busy\n");
  const replaced = runArgv(Argv.forAction(fake, { type: "read" }), { FAKE_EXIT: "1", FAKE_STDOUT: "" });
  assert.equal(replaced.stdout, "", "FAKE_STDOUT replaces the envelope");
  const unknown = runArgv([fake, "--json", "frob"]);
  assert.equal(unknown.code, 1);
  assert.match(unknown.stderr, /no contract reply/);
});

// The real binary, when one is at hand, under an environment that names
// every path todocli reads (HOME, XDG_*, TODOCLI_CONFIG, TODOCLI_DB): the
// live store, config, state directory and note are never touched. Skipped
// without a binary unless TODOCLI_REQUIRE_BIN is set (CI).
function todocliBin() {
  if (process.env.TODOCLI_BIN) return process.env.TODOCLI_BIN;
  for (const d of (process.env.PATH || "").split(path.delimiter)) {
    const p = path.join(d, "todocli");
    if (d && fs.existsSync(p)) return p;
  }
  return null;
}

test("the real todocli under an isolated environment prints the shapes the goldens hold", (t) => {
  const bin = todocliBin();
  if (!bin) {
    assert.equal(process.env.TODOCLI_REQUIRE_BIN, undefined, "TODOCLI_REQUIRE_BIN is set but no todocli is at hand");
    t.skip("no todocli binary (TODOCLI_BIN unset, none on PATH)");
    return;
  }
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "todo-contract-"));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  const home = path.join(root, "home");
  fs.mkdirSync(home, { recursive: true, mode: 0o700 });
  const env = {
    HOME: home, XDG_CONFIG_HOME: path.join(root, "xdg", "config"), XDG_DATA_HOME: path.join(root, "xdg", "data"),
    XDG_STATE_HOME: path.join(root, "xdg", "state"), XDG_CACHE_HOME: path.join(root, "xdg", "cache"),
    TODOCLI_CONFIG: path.join(root, "config.toml"), TODOCLI_DB: path.join(root, "todo.sqlite3"),
    PATH: "/usr/bin:/bin", LANG: "C.UTF-8", TZ: "UTC"
  };
  const run = (action) => {
    const r = spawnSync(bin, Argv.forAction(bin, action).slice(1), { env, encoding: "utf8", cwd: home });
    return { code: r.status, stdout: r.stdout || "", stderr: r.stderr || "", spawnFailed: !!r.error };
  };
  const shape = (json) => Object.keys(JSON.parse(json));
  const add = run({ type: "add", name: "Buy milk --json", description: "Semi-skimmed" });
  assert.equal(add.code, 0, add.stderr);
  assert.deepEqual(shape(add.stdout), shape(golden("write-add.json")));
  const id = String(JSON.parse(add.stdout).id);
  assert.equal(Queue.rememberId({}, "tmp", add.stdout).tmp, id);
  for (const [action, name] of [
    [{ type: "setStatus", id, status: "doing" }, "write-start.json"],
    [{ type: "setStatus", id, status: "done" }, "write-done.json"],
    [{ type: "setStatus", id, status: "todo" }, "write-reopen.json"],
    [{ type: "focus", id: "clear" }, "write-focus-clear.json"],
    [{ type: "remove", id }, "write-rm.json"]
  ]) {
    const r = run(action);
    assert.equal(r.code, 0, name + ": " + r.stderr);
    assert.deepEqual(shape(r.stdout), shape(golden(name)), name);
  }
  const board = run({ type: "read" });
  assert.equal(board.code, 0, board.stderr);
  assert.deepEqual(shape(board.stdout), shape(golden("board.json")), "board --json keys: a todocli older than the goldens (no `stamp`) needs reinstalling from the crate, or name a build with TODOCLI_BIN");
  const doc = Store.fromCli(board.stdout);
  assert.equal(doc.ok, true);
  assert.deepEqual(doc.items, [], "the removed task is gone");
  assert.equal(Store.stampDir(doc.stamp), path.join(root, "xdg", "state", "todocli") + "/", "the stamp lives in the isolated state dir");
  assert.deepEqual(doc.sync.map((s) => s.name), ["obsidian"]);
  const sync = run({ type: "syncNow" });
  assert.equal(sync.code, 0, sync.stderr);
  assert.deepEqual(shape(sync.stdout), shape(golden("sync-all.json")));
  assert.equal(Errors.classifySync(sync.code, sync.stdout, sync.stderr, false), null);
  const missing = spawnSync(bin, ["--source", "omarchy", "--json", "show", "9"], { env, encoding: "utf8", cwd: home });
  assert.equal(missing.status, 1);
  assert.deepEqual(shape(missing.stdout), shape(golden("envelope-not_found.json")));
  assert.equal(missing.stdout, golden("envelope-not_found.json"), "the envelope carries no path, so its bytes are the golden's");
  assert.equal(Errors.parseEnvelope(missing.stdout).kind, "not_found");
  assert.ok(!fs.existsSync(path.join(os.homedir(), ".local", "state", "todocli", "contract-probe")), "nothing outside the sandbox");
});
